        if (pretty) formatPrettyArray(elements)
        else "[" + elements.mkString(", ") + "]"
      case JsonObject(fields) =>
        val entries = fields.map { case (k, v) =>
          "\"" + escapeJson(k) + "\": " + toJsonString(v)
        }
        if (pretty) formatPrettyObject(entries)
        else "{" + entries.mkString(", ") + "}"
    }
  }

  private def escapeJson(s: String): String =
    s.replace("\\", "\\\\")
      .replace("\"", "\\\"")
      .replace("\n", "\\n")
      .replace("\r", "\\r")
      .replace("\t", "\\t")

  private def formatPrettyArray(elements: List[String]): String = {
    if (elements.isEmpty) "[]"
    else {
      val indented = elements.map(e => indent(e, 2)).mkString(",\n")
      "[\n" + indented + "\n]"
    }
  }

  private def formatPrettyObject(entries: Iterable[String]): String = {
    if (entries.isEmpty) "{}"
    else {
      val indented = entries.map(e => indent(e, 2)).mkString(",\n")
      "{\n" + indented + "\n}"
    }
  }

  private def indent(s: String, spaces: Int): String =
    s.linesIterator.map(" " * spaces + _).mkString("\n")

  def tokenize(value: JsonValue): Token =
    Token(toJsonString(value), TokenType.Structured, Map("json" -> true))

  def tokenizePath(value: JsonValue, path: String): Option[Token] = {
    val parts = path.split("\\.")
    navigatePath(value, parts.toList).map(tokenize)
  }

  private def navigatePath(current: JsonValue, parts: List[String]): Option[JsonValue] = {
    parts match {
      case Nil => Some(current)
      case head :: tail =>
        current match {
          case JsonObject(fields) =>
            fields.get(head).flatMap(navigatePath(_, tail))
          case JsonArray(items) =>
            Try(head.toInt).toOption
              .filter(idx => idx >= 0 && idx < items.length)
              .flatMap(idx => navigatePath(items(idx), tail))
          case _ => None
        }
    }
  }
}

// ============================================================================
// Whitespace Tokenizer - Basic Text Tokenization
// ============================================================================

class WhitespaceTokenizer(
    lowercase: Boolean = false,
    minLength: Int = 0,
    maxLength: Option[Int] = None,
    stripPunctuation: Boolean = false
) {
  private val punctuation: Set[Char] =
    ".,!?;:'\"()[]{}".toSet

  private def processToken(word: String): Option[String] = {
    var processed = word

    if (stripPunctuation) {
      processed = processed.dropWhile(punctuation.contains).reverse.dropWhile(punctuation.contains).reverse
    }

    if (lowercase) {
      processed = processed.toLowerCase
    }

    if (processed.length < minLength) return None

    maxLength.foreach { max =>
      if (processed.length > max) {
        processed = processed.take(max)
      }
    }

    if (processed.isEmpty) None else Some(processed)
  }

  def tokenize(text: String): List[Token] = {
    val words = text.split("\\s+").filter(_.nonEmpty)
    words.zipWithIndex.flatMap { case (word, i) =>
      processToken(word).map { processed =>
        Token(
          value = processed,
          tokenType = TokenType.StringType,
          metadata = Map("position" -> i, "original" -> word)
        )
      }
    }.toList
  }

  def tokenizeToStrings(text: String): List[String] =
    tokenize(text).map(_.value)

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val result = mutable.ListBuffer.empty[(String, Int, Int)]
    var currentPos = 0

    for (word <- text.split("\\s+").filter(_.nonEmpty)) {
      val start = text.indexOf(word, currentPos)
      val end = start + word.length

      processToken(word).foreach { processed =>
        result += ((processed, start, end))
      }

      currentPos = end
    }

    result.toList
  }

  def countTokens(text: String): Int =
    tokenize(text).length
}

// ============================================================================
// Builder Pattern with Fluent Interface
// ============================================================================

class TokenizerBuilder[T] {
  private val _normalizers: mutable.ListBuffer[String => String] = mutable.ListBuffer.empty
  private val _validators: mutable.ListBuffer[T => Boolean] = mutable.ListBuffer.empty
  private var _metadata: Map[String, Any] = Map.empty

  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] = {
    _normalizers += normalizer
    this
  }

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] = {
    _validators += validator
    this
  }

  def withMetadata(entries: (String, Any)*): TokenizerBuilder[T] = {
    _metadata = _metadata ++ entries.toMap
    this
  }

  def build(): T => Token = {
    val normalizers = _normalizers.toList
    val validators = _validators.toList
    val metadata = _metadata

    (value: T) => {
      validators.foreach { validator =>
        if (!validator(value))
          throw new IllegalArgumentException(s"Validation failed for $value")
      }

      var strValue = value.toString
      normalizers.foreach { normalizer =>
        strValue = normalizer(strValue)
      }

      Token(strValue, TokenType.StringType, metadata)
    }
  }
}
